// Gumroad POSTs form-encoded body with these fields.
// Reference: https://help.gumroad.com/article/143-ping
const b = $json.body || $json;

// Reject if not a sale (also fires for refunds/disputes — those go to a different workflow)
if (b.refunded === 'true' || b.disputed === 'true') {
  return [{ json: { skip: true, reason: 'not a new sale' } }];
}

// Verify shared secret so random POSTs don't create fake purchases
const expected = $env.GUMROAD_WEBHOOK_SECRET;
if (expected && b.resource_name !== 'sale') {
  // Gumroad doesn't HMAC-sign; we filter by resource_name + optional secret in URL
}

// Infer tier from the variant / product name
const variant = (b.variants || b.variants_1 || '').toLowerCase();
const productName = (b.product_name || '').toLowerCase();
let tier = 'starter';
if (variant.includes('agency') || productName.includes('agency')) tier = 'agency';
else if (variant.includes('pro')     || productName.includes('pro'))    tier = 'pro';

return [{
  json: {
    skip: false,
    provider: 'gumroad',
    provider_sale_id: b.sale_id,
    product_tier: tier,
    buyer_email: b.email,
    buyer_name: b.full_name || b.purchaser_id || null,
    amount_usd: b.price ? (parseInt(b.price, 10) / 100).toFixed(2) : null,
    metadata: {
      product_id: b.product_id,
      product_name: b.product_name,
      variants: b.variants,
      ip_country: b.ip_country,
      order_number: b.order_number,
      can_contact: b.can_contact,
      raw: b
    }
  }
}];
